using System.Text;
using Microsoft.CodeAnalysis.CSharp;

namespace UiTestGen.Generation;

/// <summary>Små hjälpare för att skriva giltig C#: strängliteraler, namn och sidhuvud.</summary>
internal static class CSharp
{
    public static readonly string Header = string.Join('\n',
        "// <auto-generated>",
        "// Den här filen skrivs om av uitestgen och ska inte ändras för hand.",
        "// Egna tillägg skrivs i motsvarande fil utan .g i namnet.",
        "// </auto-generated>",
        // Utan det räknas filen som genererad kod och får inga nullable-anteckningar (CS8669 för t.ex. string?).
        "#nullable enable");

    /// <summary>En vanlig strängliteral med citattecken. å, ä och ö skrivs som de är.</summary>
    public static string Literal(string text)
    {
        var sb = new StringBuilder("\"");
        foreach (var c in text)
        {
            switch (c)
            {
                case '"': sb.Append("\\\""); break;
                case '\\': sb.Append("\\\\"); break;
                case '\n': sb.Append("\\n"); break;
                case '\r': sb.Append("\\r"); break;
                case '\t': sb.Append("\\t"); break;
                case var _ when char.IsControl(c) || (int)c is 0x2028 or 0x2029: sb.Append("\\u").Append(((int)c).ToString("x4")); break;
                default: sb.Append(c); break;
            }
        }
        return sb.Append('"').ToString();
    }

    /// <summary>Ett giltigt namn: bokstäver, siffror och understreck, aldrig en siffra först.</summary>
    public static string Identifier(string text, string fallback)
    {
        var sb = new StringBuilder();
        foreach (var c in text) sb.Append(char.IsLetterOrDigit(c) || c == '_' ? c : '_');
        if (sb.Length == 0) return fallback;
        return char.IsDigit(sb[0]) ? "_" + sb : sb.ToString();
    }

    /// <summary>Namnet med @ framför om det är ett nyckelord i C#.</summary>
    public static string Safe(string name) => SyntaxFacts.GetKeywordKind(name) != SyntaxKind.None ? "@" + name : name;

    /// <summary>Namnrymden för projektet: projektnamnet med ogiltiga tecken ersatta.</summary>
    public static string Namespace(string projectName) =>
        string.Join('.', projectName.Split('.', StringSplitOptions.RemoveEmptyEntries).Select(p => Identifier(p, "_")).DefaultIfEmpty("UiTests"));

    /// <summary>
    /// Den handskrivna delen av en genererad klass: en tom <c>partial</c>-klass med en kommentar. Filen skrivs bara om den inte finns.
    /// </summary>
    /// <param name="ns">Hela namnrymden, t.ex. <c>Shop.UiTests.Pages</c>.</param>
    public static string HandwrittenPartial(string ns, string className, string comment)
    {
        var w = new CodeWriter();
        w.Line($"namespace {ns};");
        w.Line();
        w.Line($"// {comment} Den här filen skrivs aldrig över av uitestgen.");
        w.Line($"public partial class {className}");
        w.Line("{");
        w.Line("}");
        return w.ToString();
    }

    /// <summary>Text i en radkommentar: en rad, utan radbrytningar.</summary>
    public static string Comment(string text) => text.ReplaceLineEndings(" ");
}
